    transitionConversationStatus(run.conversation, state, timestamp, run.phases);
    run.turnActive = true;
    await service.persistCheckpoint(run);
    emitRunEvent(run, { type: 'userMessage', userMessage });
    emitRunEvent(run, { state, type: 'state' });
}

